// TH18 v1.00a st04bs.ecl.txt:355-515 = B::Boss3 (non-spell before Card3), ranks 0..3.
// Source t0 = timerReset B:368. Training shell: a control enemy at (0,0) owns the
// non-spell; the real boss (0,128) is spawned by the phase pattern after the 120-frame
// opening buffer, so it also leaves with the phase tree.
const TIME_LIMIT: int = 2522;   // 120 buffer + source 2400 timeout + 2 spawn frames
const SOURCE_LIMIT: int = 2400; // B:389 setInterrupt slot0 timer

const TH18_YIN_YANG_R: int = 1056; // source etSprite type 44, base radius 10
const TH18_YIN_YANG_L: int = 1072; // source etSprite type 45, base radius 10
const TH18_DROPLET: int = 896;     // source etSprite type 34, base radius 2.4

// B:438/441 (type45) and B:469/472 (type44): ANGLE_ACCEL a=160, r=0.002 px/frame,
// s=+-0.012217305 rad/frame (=0.7deg/frame). ANIM a=1 retreats 4*speed: speed 1.5
// => sh_dist(-6fx). OFFSCREEN a=600 b=0 from B:439/470.
xformdef YIN_L {
    offscreen_keep(600);
    set_accel(0.002fx);
    set_ang_vel(0.7deg);
    @160 add_speed(0fx);
    set_accel(0fx);
    set_ang_vel(0deg);
}
xformdef YIN_R {
    offscreen_keep(600);
    set_accel(0.002fx);
    set_ang_vel(-0.7deg);
    @160 add_speed(0fx);
    set_accel(0fx);
    set_ang_vel(0deg);
}
// B:496-498: ANIM a=1 (speed 0.6 => -2.4px), WAIT 120, VELTIME a=120 target 2.5
// keeping the current direction (angle sentinel -9999994).
xformdef DROPLET {
    wait(120);
    step_speed(2.5fx, 120);
}

// B:417-475 Boss3_at: et0 first, then et1 after the rank wait.
async sub boss3_at() {
    var rank: int = global(GVAR_RANK);
    var n: int = 14;
    if rank == 1 { n = 28; }
    if rank == 2 { n = 28; }
    if rank == 3 { n = 30; }
    sh_reset(0);
    sh_sprite(0, TH18_YIN_YANG_L, 6);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, n, 1);
    sh_angle(0, -90deg, 10deg); // B:436 etAngle(-1.5707964, 0.17453292), mode3 ring
    sh_speed(0, 1.5fx, 0fx);
    sh_dist(0, -6fx);
    sh_xform(0, YIN_L);
    sh_fire(0);
    var pause: int = 50;
    if rank == 2 { pause = 40; }
    if rank == 3 { pause = 35; }
    wait(pause);
    sh_reset(1);
    sh_sprite(1, TH18_YIN_YANG_R, 5);
    sh_aim(1, 0);
    sh_ring(1, 1);
    sh_count(1, n, 1);
    sh_angle(1, -90deg, 10deg); // B:467
    sh_speed(1, 1.5fx, 0fx);
    sh_dist(1, -6fx);
    sh_xform(1, YIN_R);
    sh_fire(1);
}

// B:477-514 Boss3_at2: et2, five 20-frame bursts, then 120 frames; 80 outer rounds
// (phase timeout ends it earlier). B:505 re-randomizes the ring base each burst.
async sub boss3_at2() {
    var rank: int = global(GVAR_RANK);
    var n: int = 12;
    if rank >= 1 { n = 24; }
    wait(60); // B:480
    sh_reset(2);
    sh_sprite(2, TH18_DROPLET, 2);
    sh_aim(2, 0);
    sh_ring(2, 1);
    sh_count(2, n, 1);
    sh_speed(2, 0.6fx, 0fx);
    sh_dist(2, -2.4fx);
    sh_xform(2, DROPLET);
    for outer in 0..80 {
        for inner in 0..5 {
            sh_angle(2, (rand(65536) - 32768) as angle, 0deg); // %RANDRAD
            sh_fire(2);
            wait(20);
        }
        wait(120);
    }
}

// moveRand B:401. Same native recipe as movement.md, with this phase's
// moveLimit(0,128,280,96) B:366: outer x[-140,140] y[80,176], inner x+-70 y[104,152].
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.7fx * ((60 - k) as fx) / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// Same enemy as the stage-4 boss: hurtbox 40/2, hitbox 48/2, invulnerable for the
// practice shell. Source entry position is the boss anchor (0,128), zero velocity.
async sub boss3_main() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    wait(90);  // B:391
    // B:392 EffChargePoint3 is presentation only.
    wait(80);  // B:393
    // B:394-395 I0=60/I1=1 are not read by the subs Boss3 actually starts (at3 is
    // uncalled for this phase), so the movement helper owns int slot0 and fx0/fx1.
    spawn boss3_at2(); // B:396
    var tail: int = 90;
    if global(GVAR_RANK) == 2 { tail = 70; }
    if global(GVAR_RANK) == 3 { tail = 60; }
    loop {
        spawn boss3_at(); // B:399
        wait(10);         // B:400
        card_move_rand(); // B:401 moveRand(60,4,0.7), non-blocking interpolation
        card_wait(tail);  // B:402-411 rank wait 90/90/70/60
    }
}

async sub pattern() {
    wait(120); // opening buffer before the attack is activated
    _ = spawn_enemy(0fx, 128fx, 19400, 0, 0, 0, boss3_main);
}

async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    // Shell cleanup: the spawned real boss is not part of the phase task tree.
    kill_all_enemies(KILL_SILENT);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    loop { wait(600); }
}
